#!/usr/bin/env python3
"""Build the evidence-first LabVIEW / Blueprint / Simulink dictionary.

This is research-only.  It embeds real captured vendor UI for claims about the
three reference tools, and pairs every useful gap with an original SystemSketch
block/port/cable sketch.  The sibling Markdown is the canonical prose source.
"""

from __future__ import annotations

import base64
import html
import io
import subprocess
from dataclasses import dataclass
from pathlib import Path

from PIL import Image


REPO = Path(__file__).resolve().parents[1]
DOCS = REPO / "docs"
ASSETS = DOCS / "assets"
OUTPUT = DOCS / "labview-blueprint-simulink-vocabulary-controls-gap-analysis-2026-09-03.html"
SOURCE_NOTE = DOCS / "labview-blueprint-simulink-vocabulary-controls-gap-analysis-2026-09-03.md"


def git(*args: str) -> str:
    return subprocess.run(
        ["git", *args], cwd=REPO, text=True, capture_output=True, check=False
    ).stdout.strip()


def esc(value: object) -> str:
    return html.escape(str(value), quote=True)


def link(label: str, url: str) -> str:
    return f'<a href="{esc(url)}" target="_blank" rel="noreferrer">{esc(label)}</a>'


@dataclass(frozen=True)
class Evidence:
    image: str
    label: str
    source: str
    url: str


@dataclass(frozen=True)
class Current:
    image: str
    label: str
    seam: str


@dataclass(frozen=True)
class Entry:
    term: str
    status: str  # have | useful | skip
    description: str
    links: tuple[tuple[str, str], ...] = ()
    current: tuple[Current, ...] = ()
    evidence: tuple[Evidence, ...] = ()
    proposal: str = ""
    lift: str = ""


def image_uri(name: str, max_width: int = 980) -> str | None:
    """Return a report-portable image; screenshots remain local source assets."""
    path = ASSETS / name
    if not path.exists():
        return None
    image = Image.open(path).convert("RGB")
    if image.width > max_width:
        ratio = max_width / image.width
        image = image.resize(
            (max_width, max(1, round(image.height * ratio))), Image.Resampling.LANCZOS
        )
    buffer = io.BytesIO()
    image.save(buffer, format="JPEG", quality=86, optimize=True)
    return "data:image/jpeg;base64," + base64.b64encode(buffer.getvalue()).decode("ascii")


def current_figure(item: Current) -> str:
    uri = image_uri(item.image)
    if uri is None:
        return f'<figure class="evidence missing"><div>Current capture missing.</div><figcaption>{esc(item.label)} · <code>{esc(item.seam)}</code></figcaption></figure>'
    return f'<figure class="evidence current"><img src="{uri}" alt="{esc(item.label)}"><figcaption>{esc(item.label)} · current SystemSketch UI · <code>{esc(item.seam)}</code></figcaption></figure>'


def source_figure(item: Evidence) -> str:
    uri = image_uri(item.image)
    if uri is None:
        return f'<figure class="evidence missing"><div>Reference capture missing.</div><figcaption>{esc(item.label)} · {link(item.source, item.url)}</figcaption></figure>'
    return f'<figure class="evidence"><img src="{uri}" alt="{esc(item.label)}"><figcaption>{esc(item.label)} · {link(item.source, item.url)}</figcaption></figure>'


def proposal(label: str, inner: str, note: str) -> str:
    """Original sketch; deliberately uses SystemSketch grammar rather than vendor art."""
    return f'''<figure class="proposal"><svg viewBox="0 0 760 290" role="img" aria-label="{esc(label)}"><title>{esc(label)}</title><defs>
<marker id="arrow" markerWidth="8" markerHeight="8" refX="7" refY="4" orient="auto"><path d="M0 0 L8 4 L0 8z" fill="currentColor"/></marker>
</defs>{inner}</svg><figcaption><b>Original SystemSketch projection.</b> {note}</figcaption></figure>'''


